"""Local console UI. Human approval cannot be generated by the LLM."""
import argparse
import json
from pathlib import Path

from .agent import EngineeringAgent
from .storage import read_json


def display(result):
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0 if result['execution_status'] == 'SUCCESS' else 2


def main(argv=None):
    parser = argparse.ArgumentParser(description='GAP: запрос -> LLM -> проверяемый план -> MCP -> отчёт')
    parser.add_argument('--workspace', type=Path, default=Path(__file__).resolve().parents[1])
    commands = parser.add_subparsers(dest='command', required=True)
    request = commands.add_parser('request', help='Разобрать запрос настоящей LLM')
    request.add_argument('text')
    approve = commands.add_parser('approve', help='Локально подтвердить точный план')
    approve.add_argument('--run-id', required=True)
    approve.add_argument('--operator', required=True)
    approve.add_argument('--sha256', required=True)
    execute = commands.add_parser('execute')
    execute.add_argument('--run-id', required=True)
    acknowledge = commands.add_parser('acknowledge', help='Зафиксировать ручной разбор после неопределённого исхода; не отменяет GAP')
    acknowledge.add_argument('--run-id', required=True)
    acknowledge.add_argument('--operator', required=True)
    acknowledge.add_argument('--note', required=True)
    commands.add_parser('chat', help='Интерактивный запуск с просмотром и подтверждением плана')
    commands.add_parser('doctor', help='Диагностика файлов и настроек без LLM и без GAP')
    args = parser.parse_args(argv)
    if args.command == 'doctor':
        from .diagnostics import doctor
        return display(doctor(args.workspace))
    agent = EngineeringAgent(args.workspace)
    if args.command == 'request':
        return display(agent.request(args.text))
    if args.command == 'approve':
        return display(agent.approve(args.run_id, args.operator, args.sha256))
    if args.command == 'execute':
        return display(agent.execute(args.run_id))
    if args.command == 'acknowledge':
        return display(agent.acknowledge(args.run_id, args.operator, args.note))
    print('GAP-агент. Для выхода введи /exit. Подтверждение относится только к показанному плану.')
    while True:
        try:
            text = input('\nЗапрос> ').strip()
            if text == '/exit':
                return 0
            if not text:
                continue
            result = agent.request(text)
            display(result)
            if result['execution_status'] == 'CONFIRMATION_REQUIRED':
                plan = result['plan']
                print('\nЦелевая копия:', plan['target_model_path'])
                print('Действия:', json.dumps(plan['actions'], ensure_ascii=False))
                token = 'ПОДТВЕРЖДАЮ ' + plan['sha256'][:12]
                if input('Для записи введи «' + token + '», иначе Enter: ').strip() != token:
                    print('План не подтверждён; запись не выполнялась.')
                    continue
                operator = input('Имя подтвердившего: ').strip()
                approved = agent.approve(result['run_id'], operator, plan['sha256'])
                display(approved)
                if approved['execution_status'] == 'SUCCESS':
                    display(agent.execute(result['run_id']))
        except (KeyboardInterrupt, EOFError):
            print('\nВыход. Неопределённый исход GAP не считается отменой операции.')
            return 0

